const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    terminal: false
});

let lines = [];
let lineCount = 0;

rl.on('line', (line) => {
    lines.push(line);
    lineCount++;
    if (lineCount === 2) {
        processLines();
    }
});

function processLines() {
    // Wait for all lines to be read
    rl.on('close', () => {
        solve(lines);
    });
}

function solve(lines) {
    const firstLine = lines[0].split(' ').map(Number);
    const n = firstLine[0];
    const k = firstLine[1];

    const a = lines[1].split(' ').map(Number);

    const adj = Array.from({ length: n + 1 }, () => []);

