        const parts = lines[i].split(' ').map(Number);
        const u = parts[0];
        const v = parts[1];
        adj[u].push(v);
        adj[v].push(u);
    }

    // We need to find the maximum possible minimum value among the first k nodes in a DFS preorder traversal.
    // We can choose the root and the order of neighbors.

    // Key insight: The first k nodes in a DFS preorder traversal form a connected subgraph (a tree) that contains the root.
    // Actually, the first k nodes in DFS preorder form a connected set where each node (except the first) is connected to a previous node in the set.
    // More precisely, the set of first k nodes in a DFS preorder traversal is a connected subgraph, and the root is one of them.
